#include <stdio.h>
#include <string.h>
#include <sys/mman.h>

static void show(const char *when) {
    FILE *f = fopen("/proc/self/status", "r");
    char line[128];
    printf("%-24s", when);
    while (fgets(line, sizeof line, f)) {
        if (!strncmp(line, "VmSize:", 7) || !strncmp(line, "VmRSS:", 6)) {
            char name[16];
            long kb;
            sscanf(line, "%15s %ld", name, &kb);
            printf(" %s %4ld MB", name, kb / 1024);
        }
    }
    printf("\n");
    fclose(f);
}

int main(void) {
    size_t size = 200UL << 20;
    show("at start:");
    char *p = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    show("mapped 200 MB:");
    memset(p, 1, size / 2);
    show("touched 100 MB:");
    memset(p, 1, size);
    show("touched all 200 MB:");
    return 0;
}

#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <unistd.h>

int main(void) {
    int fd = open("big.bin", O_RDONLY);
    struct stat st;
    fstat(fd, &st);
    char *p = mmap(NULL, st.st_size, PROT_READ, MAP_SHARED, fd, 0);
    long sum = 0;
    for (off_t i = 0; i < st.st_size; i += 4096)    /* touch one byte per page */
        sum += p[i];
    char cmd[200];
    snprintf(cmd, sizeof cmd,
             "grep big.bin /proc/%d/maps | cut -c1-70; grep -E '^(Rss|Private_Clean|Private_Dirty)' /proc/%d/smaps_rollup",
             getpid(), getpid());
    system(cmd);
    return 0;
}

